import {PROJECT,CAPABILITIES} from './seed.mjs';
import {Store,ROLES,MONEY_FIELDS,cents,net,gross,receiptNet,can,packages,budgetTotals,monthlyCash,saveSettlement,saveFinance,saveContract,saveBudget,saveExpense,saveReceipt,saveParty,csv} from './model.mjs';

let storage;try{storage=window.localStorage;}catch{}
const store=new Store(storage);
const ui={page:'overview',scope:'SC',workspace:'commercial',currency:'EUR',role:'admin',query:'',filter:'all',expanded:new Set(),detail:false,ownerTab:'receipts',masterTab:'contracts',area:'',month:'2026-09',tour:-1,menu:false};
const $=s=>document.querySelector(s);
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,currency=ui.currency)=>n==null?'—':new Intl.NumberFormat('en-GB',{style:'currency',currency,maximumFractionDigits:2,minimumFractionDigits:2}).format(n/100);
const shortMoney=(n,currency=ui.currency)=>new Intl.NumberFormat('en-GB',{style:'currency',currency,notation:'compact',maximumFractionDigits:2}).format(n/100);
const pct=n=>n==null?'Unknown':(n*100).toFixed(1)+'%';
const num=(n,currency)=>`<span class="amount">${money(n,currency)}</span>`;
const tag=(text,type='')=>`<span class="tag ${type}">${E(text)}</span>`;
const db=()=>store.db;
const party=c=>db().parties.find(p=>p.id===c?.partyId);
const contract=s=>db().contracts.find(c=>c.id===s.contractId);
const ability=cap=>can(db(),ui.role,cap);
const selected=(a,b)=>a===b?' selected':'';
const checked=v=>v?' checked':'';
const decimal=v=>((v||0)/100).toFixed(2);
const iconPaths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',file:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h5',plus:'M12 5v14 M5 12h14',bars:'M5 20V10 M12 20V4 M19 20V14',chart:'M3 19h18 M4 15l5-6 5 3 6-8',folder:'M3 6h7l2 3h9v11H3z',people:'M9 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-3c0-5 14-5 14 0v3 M17 4c5 0 5 8 0 8 M20 21v-4',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',map:'M3 6l6-3 6 3 6-3v15l-6 3-6-3-6 3z M9 3v15 M15 6v15',wallet:'M3 5h17v15H3z M15 11h6v5h-6z',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L19 6',alert:'M12 3L2 21h20z M12 9v5 M12 17h.01',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};
const icon=(name='grid')=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.grid}"/></svg>`;
const button=(text,action,extra='',type='')=>`<button class="btn ${type}" data-action="${action}" ${extra}>${E(text)}</button>`;
const head=(title,desc,actions='',eyebrow='PROJECT COMMERCIAL CONTROL')=>`<div class="page-top"><div><p class="eyebrow">${E(eyebrow)}</p><h1>${E(title)}</h1><p>${E(desc)}</p></div><div class="page-actions">${actions}<label class="currency">Currency <select id="currency" aria-label="Report currency"><option${selected(ui.currency,'EUR')}>EUR</option><option${selected(ui.currency,'USD')}>USD</option></select></label></div></div>`;
const metric=(label,value,note,ico='chart')=>`<div class="metric"><div class="metric-top">${E(label)}<span class="metric-icon">${icon(ico)}</span></div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;
const panel=(title,subtitle,body,extra='')=>`<section class="panel"><div class="panel-header"><div><h2>${E(title)}</h2>${subtitle?`<p>${E(subtitle)}</p>`:''}</div>${extra}</div>${body}</section>`;
const empty=(label='No matching records',detail='Try another currency or clear your filters.')=>`<div class="empty"><strong>${E(label)}</strong>${E(detail)}</div>`;
const table=(headers,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th${h.startsWith('#')?' class="num"':''}>${E(h.replace(/^#/,''))}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty();
const notice=(text,warn=false)=>`<div class="notice ${warn?'warn':''}">${icon(warn?'alert':'shield')}<span>${text}</span></div>`;
const searchBar=(extra='')=>`<div class="toolbar"><div class="filters"><input class="search" id="search" type="search" aria-label="Search records" placeholder="Search name or reference…" value="${E(ui.query)}">${extra}</div><span class="scope-badge">${E(ui.scope)} · ${ui.currency}</span></div>`;
const matches=(...values)=>values.join(' ').toLowerCase().includes(ui.query.toLowerCase());
const visibleContracts=()=>db().contracts.filter(c=>c.scope===ui.scope&&c.currency===ui.currency);
const visibleSettlements=()=>db().settlements.filter(s=>s.scope===ui.scope&&s.currency===ui.currency);
const footer=()=>`<footer class="footer"><span>Designed and built by Hanchen Wang · Portfolio edition</span><span>Northstar Industrial Campus · All records are fictional</span></footer>`;
const pages={overview:['Project overview','grid'],entry:['New settlement','plus'],ledger:['Settlement ledger','file'],budget:['Execution budget','book'],analysis:['Budget analysis','bars'],construction:['Construction analysis','grid'],cashflow:['Monthly cash flow','chart'],progress:['Progress view','chart'],areas:['Project areas','map'],parties:['Counterparties','people'],contracts:['Contract preview','folder'],master:['Master data','settings'],owner:['Owner','book'],expenses:['Other expenses','wallet'],users:['Users & permissions','shield'],audit:['Audit trail','clock'],errors:['Error log','alert'],about:['About this project','book']};
const groups=[['WORK',['overview','entry','ledger','owner','expenses']],['COST & ANALYSIS',['budget','analysis','construction','cashflow','progress']],['PROJECT DATA',['areas','parties','contracts','master']],['GOVERNANCE',['users','audit','errors','about']]];
function visiblePage(page){if(page==='entry')return ability('settlementEdit')&&ui.workspace==='commercial';if(page==='areas')return ui.scope==='SC'&&ui.workspace==='commercial';if(['contracts','parties','progress','construction'].includes(page))return ui.workspace==='commercial';if(page==='users')return ui.role==='admin';if(['audit','errors'].includes(page))return ability('audit');return true;}
function shell(content){return `<header class="topbar"><div class="brand"><button class="menu-toggle" data-action="menu" aria-label="Toggle navigation">☰</button><span class="brand-mark">${icon('bars')}</span><div><strong>Project Commercial Control</strong><small>Contracts · Settlements · Finance · Governance</small></div></div><div class="top-actions">${button('About this project','navigate','data-page="about"')}<label>DEMO ROLE<select id="role" aria-label="Demo role">${Object.entries(ROLES).map(([id,name])=>`<option value="${id}"${selected(ui.role,id)}>${name}</option>`).join('')}</select></label><div class="author"><span class="avatar">HW</span><div><strong>Hanchen Wang</strong><small>Project creator</small></div></div></div></header>${store.notice?`<div class="notice warn storage-warning" role="status">${E(store.notice)}</div>`:''}<div class="shell ${ui.menu?'menu-open':''}"><aside class="sidebar"><div><div class="side-label">Workspace</div><div class="segmented">${['commercial','finance'].map(w=>`<button data-action="workspace" data-value="${w}" class="${ui.workspace===w?'active':''}">${w==='commercial'?'Commercial':'Finance'}</button>`).join('')}</div></div><div><div class="side-label">Business scope</div><div class="scopes">${['SC','SG'].map(s=>`<button data-action="scope" data-value="${s}" class="${ui.scope===s?'active':''}">${s} records</button>`).join('')}</div></div><nav aria-label="Main navigation">${groups.map(([label,ids])=>`<section class="nav-group"><div class="side-label">${label}</div>${ids.filter(visiblePage).map(id=>`<button class="nav-button ${ui.page===id?'active':''}" data-action="navigate" data-page="${id}" ${ui.page===id?'aria-current="page"':''}>${icon(pages[id][1])}${pages[id][0]}</button>`).join('')}</section>`).join('')}</nav><div class="sidebar-bottom"><strong>A working project, explained.</strong><p>Follow a record from contract through settlement, payment and audit evidence.</p><button class="text-button" data-action="tour-start">Take the 2-minute tour →</button></div></aside><main id="main" tabindex="-1">${tourCard()}${content}${footer()}</main></div>`;}
const tour=[['overview','A connected commercial workflow','This portfolio mirrors a working platform: structured records, separate finance facts, read-only evidence and traceable changes.'],['contracts','Start with a contract','Expand a contract to see variations and supplements. Open Files for a fictional document, or follow a contract into its settlements.'],['ledger','Separate unknown amounts from zero','Amber rows have amounts awaiting confirmation. Existing payments remain visible even while a settlement amount is unknown. Try editing a record.'],['cashflow','Follow the actual cash','The report uses registered net receipts and payments. It does not treat contract values or certified amounts as cash.'],['audit','Finish with traceability','Your edits appear here with before and after values. Switch demo roles to explore the separation of duties.']];
function tourCard(){if(ui.tour<0)return '';const t=tour[ui.tour];return `<div class="tour-card"><div><small>GUIDED TOUR · ${ui.tour+1} OF ${tour.length}</small><strong>${t[1]}</strong><p>${t[2]}</p></div><div class="page-actions">${button('Close','tour-close','', 'small')}${button(ui.tour===tour.length-1?'Finish tour':'Next step →','tour-next','','small')}</div></div>`;}
function overview(){const cs=visibleContracts(),ss=visibleSettlements(),ids=new Set(ss.map(s=>s.id)),pending=ss.filter(s=>s.pending).length,paid=db().finance.filter(f=>ids.has(f.settlementId)).reduce((t,f)=>t+f.paid,0),value=cs.reduce((t,c)=>t+c.amount,0),cert=ss.reduce((t,s)=>t+(s.pending?0:s.certified),0);const bs=db().budgets.filter(b=>b.currency===ui.currency),over=bs.filter(b=>budgetTotals(db(),b).commitment>b.amount).length;
  return head('A clear view of the project.','Northstar Industrial Campus · Demonstration snapshot, September 2026',button('Explore the workflow','tour-start','','primary'))+`<div class="metrics">${metric('Committed contract value',shortMoney(value),`${cs.length} contracts and changes · ${ui.scope}`,'file')}${metric('Certified work',shortMoney(cert),`${ss.length} statements · ${pending} amount pending`,'check')}${metric('Registered net payments',shortMoney(paid),'Actual demo Finance records','wallet')}${metric('Control items',String(pending+over),`${pending} pending statements · ${over} budget exceptions`,'shield')}</div><div class="split">${panel('Project cash flow','Net receipts and actual payments · all SC/SG and other expenses',`<div class="panel-body">${cashChart()}<div class="legend"><span>Owner receipts</span><span>Payments + other expenses</span></div></div>`,button('View report','navigate','data-page="cashflow"','small'))}${panel('Requires attention','Find the next useful action',`<div class="panel-body"><div class="watch-item"><div class="watch-icon">${icon('alert')}</div><div><strong>${pending} ${ui.scope} statements await amounts</strong><p>Missing amounts stay unknown. Payment records remain independent.</p><button class="text-button" data-action="pending">Review pending records →</button></div></div><div class="watch-item"><div class="watch-icon">${icon('bars')}</div><div><strong>${over} budget lines above commitment limits</strong><p>Compare the active execution budget with contract commitments.</p><button class="text-button" data-action="navigate" data-page="analysis">Open budget analysis →</button></div></div><div class="watch-item"><div class="watch-icon">${icon('shield')}</div><div><strong>Document access is a separate control</strong><p>Contract files and guarantees have distinct demo permissions.</p><button class="text-button" data-action="navigate" data-page="contracts">Explore contract evidence →</button></div></div></div>`)}</div>`+panel('Recent settlement records','Select a record to explore the commercial and finance views',ledgerTable(ss.slice(-5)),button('All records','navigate','data-page="ledger"','small'));
}
function cashChart(){const months=['2026-07','2026-08','2026-09'],series=months.map(m=>monthlyCash(db(),m,ui.currency)),max=Math.max(1,...series.flatMap(s=>[s.income,s.expenditure]));return `<svg class="chart" viewBox="0 0 590 230" role="img" aria-label="Net owner receipts and project payments, July to September 2026">${[0,.25,.5,.75,1].map(t=>`<line x1="65" y1="${185-t*150}" x2="560" y2="${185-t*150}" class="chart-grid"/><text x="5" y="${189-t*150}">${E(shortMoney(max*t))}</text>`).join('')}${series.map((s,i)=>`<rect x="${116+i*162}" y="${185-s.income/max*150}" width="36" height="${s.income/max*150}" rx="3" fill="#31836e"/><rect x="${158+i*162}" y="${185-s.expenditure/max*150}" width="36" height="${s.expenditure/max*150}" rx="3" fill="#adc5bb"/><text x="${132+i*162}" y="211">${['JUL','AUG','SEP'][i]}</text>`).join('')}</svg>`;}
function ledgerTable(rows){return table(['Flow / reference','Contract','Date',...(ui.detail?['#Net advance','#Certified','#Retention','#HSE','#Other net']:[]),'#Net payable','#Tax','#Gross payable','#Net paid','Status','Actions'],rows.map(s=>{const c=contract(s),f=db().finance.find(f=>f.settlementId===s.id),paid=f?.paid||0;return `<tr class="${s.pending?'pending-row':''}"><td><strong>${s.scope}-${s.flow}</strong><small>${E(s.period)}</small></td><td class="name-cell"><strong>${E(c?.code)}</strong><small>${E(c?.name)}</small></td><td class="nowrap">${s.date}</td>${ui.detail?[s.advance-s.advanceRecovery,s.certified,-s.retention,-s.hse,s.additions-s.deductions].map(n=>`<td class="num">${num(s.pending?null:n,s.currency)}</td>`).join(''):''}<td class="num">${num(net(s),s.currency)}</td><td class="num">${num(s.pending?null:s.tax,s.currency)}</td><td class="num">${num(gross(s),s.currency)}</td><td class="num">${num(paid,s.currency)}</td><td>${s.pending?tag('Amount pending','amber'):s.final?tag('Final','blue'):tag('Recorded','green')}</td><td><div class="actions">${ability('settlementEdit')?button('Edit','edit-settlement',`data-id="${s.id}"`,'small'):button('View','view-settlement',`data-id="${s.id}"`,'small')}${button('Finance','finance',`data-id="${s.id}"`,'small')}</div></td></tr>`;}));}
function ledger(){let rows=visibleSettlements().filter(s=>matches(s.flow,s.period,contract(s)?.name,contract(s)?.code,party(contract(s))?.name)&&(!ui.filter.startsWith('contract:')||s.contractId===ui.filter.slice(9))&&(ui.filter!=='pending'||s.pending));const pending=visibleSettlements().filter(s=>s.pending).length;return head(ui.workspace==='finance'?'Finance settlement workspace':'Settlement ledger',`${ui.scope} records · commercial valuation and Finance payment records remain separate.`,`${button(ui.detail?'Compact columns':'All amount fields','columns')}${button('Export CSV','export-ledger')}${ability('settlementEdit')?button('New settlement','navigate','data-page="entry"','primary'):''}`)+(pending?notice(`${pending} ${ui.scope} record${pending===1?'':'s'} have unknown amounts. They are counted as records, excluded from monetary totals and never inferred as paid.`,true):'')+`<section class="panel">${searchBar(`<select id="status-filter" aria-label="Settlement status"><option value="all"${selected(ui.filter,'all')}>All records</option><option value="pending"${selected(ui.filter,'pending')}>Amount pending</option>${ui.filter.startsWith('contract:')?`<option selected value="${E(ui.filter)}">Selected contract</option>`:''}</select>${ui.filter!=='all'?button('Clear filter','clear-filter','','small'):''}`)}${ledgerTable(rows)}<div class="table-foot"><span>${rows.length} records · ${rows.filter(s=>s.pending).length} pending</span><span>Known net payable: ${money(rows.reduce((n,s)=>n+(net(s)||0),0))} · Tax shown separately</span></div></section>`;}
function contracts(){const rows=visibleContracts().filter(c=>matches(c.code,c.name,party(c)?.name));const roots=rows.filter(c=>!c.parentId||!rows.some(p=>p.id===c.parentId));let out=[];const row=(c,child=false)=>{const children=rows.filter(x=>x.parentId===c.id);out.push(`<tr class="${child?'child':''}"><td><span class="row-title">${children.length?`<button class="expand" data-action="expand" data-id="${c.id}" aria-label="${ui.expanded.has(c.id)?'Collapse':'Expand'} ${c.code}" aria-expanded="${ui.expanded.has(c.id)}">${ui.expanded.has(c.id)?'−':'+'}</button>`:''}<span><strong>${E(c.code)}</strong><small>${E(c.filing)}</small></span></span></td><td class="name-cell"><strong>${E(c.name)}</strong><small>${E(party(c)?.name)}</small></td><td>${tag(c.kind,c.kind==='VO'?'blue':'')}${c.separate?'<small>Standalone package</small>':''}</td><td class="num">${num(c.amount,c.currency)}</td><td><div class="chips">${c.areas.map(a=>`<span class="chip">${E(db().areas.find(x=>x.id===a)?.code)}</span>`).join('')||'<span class="muted">Not assigned</span>'}</div></td><td><div class="actions">${button('Files','files',`data-id="${c.id}"`,'small')}${button('Ledger','contract-ledger',`data-id="${c.id}"`,'small')}${ability('contractEdit')?button('Edit','edit-contract',`data-id="${c.id}"`,'small'):''}</div></td></tr>`);if(ui.expanded.has(c.id))children.forEach(x=>row(x,true));};roots.forEach(c=>row(c));return head('Contract preview','CT / WO roots, their variations and supplements, with direct project-area links.',button('Expand all','expand-all')+(ability('contractEdit')?button('New contract','new-contract','','primary'):''))+`<section class="panel">${searchBar()}${table(['Contract reference','Contract / counterparty','Type','#Contract value','Project areas','Actions'],out)}<div class="table-foot"><span>${rows.length} contracts and changes · ${out.length} rows displayed</span><span>Amounts shown per record; expand to inspect the hierarchy.</span></div></section>`;}
function progress(){const ps=packages(db(),ui.scope,ui.currency).filter(p=>matches(p.root.code,p.root.name));const rows=[];ps.forEach(p=>{rows.push(`<tr><td class="name-cell"><span class="row-title"><button class="expand" data-action="expand" data-id="${p.root.id}" aria-expanded="${ui.expanded.has(p.root.id)}" aria-label="Expand ${p.root.code}">${ui.expanded.has(p.root.id)?'−':'+'}</button><span><strong>${E(p.root.code)}</strong><small>${E(p.root.name)}</small></span></span></td><td>${tag(p.root.separate?'Standalone SA':p.root.kind)}</td><td class="num">${num(p.amount)}</td><td class="num">${num(p.certified)}</td><td class="num">${num(p.paid)}</td><td>${p.pending?tag('Amount pending','amber'):`${pct(p.progress)}<div class="progress-track"><span style="width:${Math.min(100,(p.progress||0)*100)}%"></span></div>`}</td></tr>`);if(ui.expanded.has(p.root.id))p.members.forEach(c=>rows.push(`<tr class="child"><td><strong>${E(c.code)}</strong><small>${E(c.name)}</small></td><td>${tag(c.kind)}</td><td class="num">${num(c.amount)}</td><td colspan="3">${button('View settlements','contract-ledger',`data-id="${c.id}"`,'small')}</td></tr>`));});return head('Progress view','Certified work as a share of contract value. This is commercial certification, not physical site progress.')+notice('Ordinary changes roll into their root contract. Standalone supplements and their descendants form separate packages. Pending amounts keep the completion ratio unknown.')+`<section class="panel">${searchBar()}${table(['Package','Basis','#Contract + changes','#Known certified','#Net paid','Certification'],rows)}</section>`;}
function budget(analysis=false){const bs=db().budgets.filter(b=>b.currency===ui.currency),total=bs.reduce((a,b)=>a+b.amount,0),commit=bs.reduce((a,b)=>a+budgetTotals(db(),b).commitment,0);return head(analysis?'Budget analysis':'Execution budget',analysis?'Compare contract commitments and known certified costs against manually maintained budget lines.':'Manual budget baselines, independent of Finance Cloud categories. Values below are fictional.',ability('budgetEdit')?'':tag('Read-only demo role'))+`<div class="metrics">${metric('Execution budget',shortMoney(total),'All project scopes in this currency','book')}${metric('Contract commitments',shortMoney(commit),'Each CT / WO / VO / SA counted once','file')}${metric('Uncommitted budget',shortMoney(total-commit),'Budget less commitments','bars')}${metric('Budget lines',String(bs.length),'Edit a line to see linked analysis update','grid')}</div>`+panel('Budget control',`All SC and SG records · ${ui.currency}`,table(['Budget subject','Version','#Budget','#Committed','#Known certified','#Available','Control','Actions'],bs.map(b=>{const t=budgetTotals(db(),b);return `<tr><td><strong>${E(b.name)}</strong><small>${b.id.toUpperCase()} · ${b.currency}</small></td><td>${E(b.version)}</td><td class="num">${num(b.amount)}</td><td class="num">${num(t.commitment)}</td><td class="num">${num(t.certified)}${t.pending?`<small>${t.pending} pending</small>`:''}</td><td class="num">${num(b.amount-t.commitment)}</td><td>${tag(t.commitment>b.amount?'Over budget':'Within budget',t.commitment>b.amount?'red':'green')}</td><td>${ability('budgetEdit')?button('Edit budget','edit-budget',`data-id="${b.id}"`,'small'):'—'}</td></tr>`;})))+notice('A settlement follows its contract budget subject unless an explicit override is selected. Unknown amounts do not become zero-valued completed costs.');}
function construction(){const ps=packages(db(),ui.scope,ui.currency),cats=[...new Set(visibleContracts().map(c=>c.category||'Unclassified'))];return head('Construction analysis','Compare classification and area views without allocating shared costs arbitrarily.')+notice('Cross-category packages retain separate contract values. Shared package certification is shown at package level; category-level ratios remain unallocated.')+panel('By construction category',`${ui.scope} · ${ui.currency} · direct contract classification`,table(['Category','#Contract value','Linked packages','#Known certified','Certification'],cats.map(cat=>{const cs=visibleContracts().filter(c=>(c.category||'Unclassified')===cat),p=ps.filter(p=>p.categories.has(cat)),cross=p.some(p=>p.categories.size>1),amount=cs.reduce((a,c)=>a+c.amount,0),cert=p.reduce((a,p)=>a+p.certified,0),pending=p.some(p=>p.pending);return `<tr><td><strong>${E(cat)}</strong></td><td class="num">${num(amount)}</td><td>${p.length}</td><td class="num">${cross?'Unallocated':num(cert)}</td><td>${cross?tag('Shared package','amber'):pending?tag('Amount pending','amber'):pct(amount?cert/amount:null)}</td></tr>`;})))+panel('Complete package context','Same package appears only once here, even when it spans multiple areas.',table(['Package','Categories','Areas','#Contract value','#Known certified'],ps.map(p=>`<tr><td><strong>${E(p.root.code)}</strong><small>${E(p.root.name)}</small></td><td>${[...p.categories].map(E).join('<br>')}</td><td><div class="chips">${[...p.areas].map(a=>`<span class="chip">${E(db().areas.find(x=>x.id===a)?.code)}</span>`).join('')}</div></td><td class="num">${num(p.amount)}</td><td class="num">${num(p.certified)}${p.pending?'<small>Incomplete</small>':''}</td></tr>`)));}
function cashflow(){const t=monthlyCash(db(),ui.month,ui.currency),fs=db().finance.filter(f=>f.paymentDate.startsWith(ui.month)&&db().settlements.find(s=>s.id===f.settlementId)?.currency===ui.currency);return head('Monthly cash flow','Project-wide cash report · all SC, SG and other expenses. Only registered amounts excluding tax are included.',`<label class="currency">Month <input type="month" id="month" aria-label="Cash-flow month" value="${ui.month}"></label>`)+`<div class="metrics">${metric('Owner net receipts',shortMoney(t.income),'Registered receipts in selected month','wallet')}${metric('Net payments',shortMoney(t.paid),'Finance payment records','wallet')}${metric('Other net expenses',shortMoney(t.other),'Outside the contract ledger','file')}${metric('Net cash flow',shortMoney(t.net),'Receipts less payments and expenses','chart')}</div><div class="split">${panel('Cash movement','Illustrative July–September reporting period',`<div class="panel-body">${cashChart()}<div class="legend"><span>Owner receipts</span><span>Payments + other expenses</span></div></div>`)}${panel('Calculation basis','Keep certification, tax and cash distinct',`<div class="panel-body small-copy"><p>Income = owner net receipts.</p><p>Expenditure = registered net Finance payments + net other expenses.</p><p>Tax and gross values remain available in their records, but are excluded from this chart and net cash flow.</p><p class="muted">The SC / SG selector does not narrow this project-wide report.</p></div>`)}</div>`+panel('Registered payment details',`${ui.month} · ${ui.currency}`,table(['Date','Reference','Contract','Invoice','#Net payment','#Tax'],fs.map(f=>{const s=db().settlements.find(s=>s.id===f.settlementId);return `<tr><td>${f.paymentDate}</td><td>${E(f.reference)}</td><td><strong>${E(contract(s)?.code)}</strong><small>${E(party(contract(s))?.name)}</small></td><td>${E(f.invoice)}</td><td class="num">${num(f.paid)}</td><td class="num">${num(f.tax)}</td></tr>`;})));}
function parties(){const rows=db().parties.filter(p=>p.scope===ui.scope&&matches(p.name,p.code));return head('Counterparties','SC and SG are explicit business codes, independent of company type.',ability('contractEdit')?button('New counterparty','new-party','','primary'):'')+`<section class="panel">${searchBar()}</section><div class="cards">${rows.map(p=>{const cs=db().contracts.filter(c=>c.partyId===p.id&&c.currency===ui.currency);return `<article class="party-card"><div class="party-code">${tag(p.code)}${tag(p.status,p.status==='Active'?'green':'')}</div><h2>${E(p.name)}</h2><p>${E(p.notes)}</p><p>${E(p.email)}</p><div class="card-stats"><div><strong>${cs.length}</strong><small>Contracts and changes</small></div><div><strong>${shortMoney(cs.reduce((a,c)=>a+c.amount,0))}</strong><small>${ui.currency} commitments</small></div></div><div class="form-actions">${button('View contracts','party-contracts',`data-id="${p.id}"`,'small')}${button('General files','party-files',`data-id="${p.id}"`,'small')}</div></article>`;}).join('')||empty()}</div>`;}
function areas(){const a=db().areas.find(a=>a.id===ui.area),cs=visibleContracts().filter(c=>!a||c.areas.includes(a.id));return head('Project areas','A fictional schematic replaces the real site plan. Select a zone to inspect its directly linked contracts.')+panel('Northstar campus','Illustrative layout only. Not a construction drawing.',`<div class="panel-body"><div class="map">${db().areas.map(a=>`<button class="zone" data-action="area" data-id="${a.id}" aria-pressed="${ui.area===a.id}"><strong>${a.code}</strong><small>${E(a.name)}</small></button>`).join('')}</div><p class="area-info">${a?E(a.code+' · '+a.name):'All areas'} · ${cs.length} ${ui.currency} contracts and changes. ${ui.area?'<button class="text-button" data-action="area" data-id="">Clear selection</button>':''}</p></div>`)+panel(a?'Contracts in '+a.name:'All contracts','Contracts spanning multiple zones remain one record.',table(['Contract','Description','Category','#Value'],cs.map(c=>`<tr><td><button class="link-button" data-action="contract-ledger" data-id="${c.id}">${c.code}</button></td><td>${E(c.name)}</td><td>${E(c.category)}</td><td class="num">${num(c.amount)}</td></tr>`)));}
function owner(){const tabs=[['receipts','Owner receipts'],...(ability('ownerDocuments')?[['Main contract','Main contract'],['Site instructions','Site instructions'],['Commercial correspondence','Correspondence'],['Main contract settlements','Main valuations']]:[])];if(!tabs.some(t=>t[0]===ui.ownerTab))ui.ownerTab='receipts';const receipts=db().receipts.filter(r=>r.currency===ui.currency);return head('Owner workspace','Owner documents and receipts are separate records; document metadata never enters cash-flow totals.',ui.ownerTab==='receipts'&&ability('ownerReceipts')?button('New receipt','new-receipt','','primary'):'')+`<div class="tabs">${tabs.map(([id,label])=>`<button data-action="owner-tab" data-value="${id}" class="${ui.ownerTab===id?'active':''}">${label}</button>`).join('')}</div>`+(ui.ownerTab==='receipts'?panel('Owner receipts','Net, tax and gross receipt values remain separate.',table(['Reference','Date','#Net advance','#Certified','#Net retention','#Net received','#Tax','#Gross received'],receipts.map(r=>`<tr><td><strong>${E(r.reference)}</strong></td><td>${r.date}</td><td class="num">${num(r.advance-r.recovery)}</td><td class="num">${num(r.certified)}</td><td class="num">${num(r.released-r.retained)}</td><td class="num">${num(receiptNet(r))}</td><td class="num">${num(r.tax)}</td><td class="num">${num(receiptNet(r)+r.tax)}</td></tr>`))):panel(ui.ownerTab,'Sample metadata and fictional read-only evidence.',table(['Reference','Title','Date','Revision','State','Evidence'],db().ownerDocs.filter(d=>d.type===ui.ownerTab).map(d=>`<tr><td><strong>${E(d.reference)}</strong></td><td>${E(d.title)}</td><td>${d.date}</td><td>${d.revision}</td><td>${tag(d.status,d.status==='Filed'?'green':'amber')}</td><td>${button('Preview','owner-document',`data-id="${d.id}"`,'small')}</td></tr>`))))+(!ability('ownerDocuments')?notice('This demo role can inspect receipt information. Owner correspondence is controlled by a separate permission.'):'');}
function expenses(){const es=db().expenses.filter(e=>e.currency===ui.currency&&matches(e.description,e.category));return head('Other expenses','Project expenses outside the contract ledger. Only net amounts enter monthly cash flow.',ability('expenses')?button('New expense','new-expense','','primary'):'')+`<section class="panel">${searchBar()}${table(['Date','Description','Category','#Net','#Tax','#Gross'],es.map(e=>`<tr><td>${e.date}</td><td><strong>${E(e.description)}</strong></td><td>${E(e.category)}</td><td class="num">${num(e.net)}</td><td class="num">${num(e.tax)}</td><td class="num">${num(e.net+e.tax)}</td></tr>`))}</section>`;}
function master(){return head('Master data','Maintain fictional records and inspect the same shared information across all workspaces.',ability('contractEdit')?button(ui.masterTab==='contracts'?'New contract':'New counterparty',ui.masterTab==='contracts'?'new-contract':'new-party','','primary'):'')+`<div class="tabs">${['contracts','parties'].map(t=>`<button data-action="master-tab" data-value="${t}" class="${ui.masterTab===t?'active':''}">${t==='contracts'?'Contracts and changes':'Counterparties'}</button>`).join('')}</div>`+(ui.masterTab==='contracts'?contracts().replace(/^.*?(?=<section class="panel">)/s,''):parties().replace(/^.*?(?=<section class="panel">)/s,''));}
function users(){return head('Users & permissions','Explore separation of duties with fictional roles. These controls simulate the production permission model.')+notice('<strong>Browser simulation, not authentication.</strong> Everyone can switch demo roles. All sample data is public; client-side permissions do not secure real information.')+`<section class="panel"><div class="panel-header"><div><h2>Capability matrix</h2><p>Change a non-administrator role, then select that role in the header.</p></div></div><div class="table-wrap"><table class="permission-table"><thead><tr><th>Capability</th>${Object.values(ROLES).map(r=>`<th>${E(r)}</th>`).join('')}</tr></thead><tbody>${Object.entries(CAPABILITIES).map(([key,label])=>`<tr><td>${E(label)}</td>${Object.keys(ROLES).map(role=>`<td>${role==='admin'?'<span class="checkmark">Included</span>':`<input type="checkbox" aria-label="${E(ROLES[role]+' — '+label)}" data-permission="${key}" data-role="${role}"${checked(can(db(),role,key))}>`}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`+notice('In the original system, server-side capability checks, authenticated users and a durable audit log enforce access. This static site demonstrates the interaction only.');}
function audit(){return head('Audit trail','Before and after values from demo edits. This local history can be reset and is not a durable audit record.')+panel('Recorded activity','Newest first. The initial entry is synthetic sample history.',table(['Time','Actor','Action','Record','Details'],db().audit.filter(a=>matches(a.actor,a.action,a.entity)).map(a=>`<tr><td class="nowrap">${E(new Date(a.at).toLocaleString('en-GB'))}</td><td>${E(a.actor)}</td><td>${tag(a.action)}</td><td>${E(a.entity)}</td><td>${button('Inspect change','audit-detail',`data-id="${a.id}"`,'small')}</td></tr>`)));}
function errors(){return head('Error log','Rejected demo actions are recorded here for diagnosis. Real application logs are not included.')+panel('Validation and local issues','Try saving a duplicate settlement reference to see a validation event.',table(['Time','Context','Message'],db().errors.map(e=>`<tr><td class="nowrap">${E(new Date(e.at).toLocaleString('en-GB'))}</td><td>${E(e.context)}</td><td>${E(e.message)}</td></tr>`)));}
function about(){return head('From scattered records to usable controls.','A project portfolio by Hanchen Wang.',button('Start guided tour','tour-start','','primary'),'THE PROJECT BEHIND THE INTERFACE')+`<section class="project-story"><div><p class="eyebrow">COMMERCIAL OPERATIONS · GOVERNANCE · TRACEABILITY</p><h2>A connected workspace for project commercial management.</h2><p>I designed and built a platform to connect contract records, settlement calculations, payment information, budgets and documentary evidence. Its purpose is to help a project team find reliable information and trace how records changed.</p>${button('Explore the live demo','navigate','data-page="overview"')}</div><div class="story-points"><div><strong>Process and control design</strong><small>Separate commercial, finance and document responsibilities.</small></div><div><strong>Structured information</strong><small>Link records through contract and counterparty identifiers.</small></div><div><strong>Practical implementation</strong><small>Turn working requirements into a usable application.</small></div></div></section><div class="split">${panel('The operational problem','Why the platform exists',`<div class="panel-body scope-note"><p>Commercial information often lives across folders, spreadsheets and individual working files. That makes it harder to find evidence, identify the current version and reconcile a settlement with its payment.</p><p>The platform creates a structured control layer around those records. It complements the required company ledger and keeps source commercial documents under human control.</p></div>`)}${panel('My contribution','Designed and built by Hanchen Wang',`<div class="panel-body scope-note"><p>Business-process mapping, commercial calculation rules, data structure, user workflows, permission boundaries, document traceability and implementation.</p><p>This portfolio focuses on the connection between commercial operations, risk awareness and practical systems delivery.</p></div>`)}</div>`+panel('Follow the record','A short route through the project',`<div class="panel-body"><div class="flow">${[['01','Contract','Register a counterparty, contract, work order and linked changes.'],['02','Settlement','Record certification, advances and deductions; preserve unknown amounts.'],['03','Finance','Keep invoices and actual payments separate from valuations.'],['04','Evidence','Inspect supporting documents and the history of record changes.']].map(([n,t,d])=>`<div class="flow-step"><span>${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div>`)+`<div class="split">${panel('Original platform architecture','A high-level description, without business data',`<div class="panel-body architecture"><div><strong>Browser interface</strong><small>Commercial and Finance workspaces</small></div><div><strong>Python application service</strong><small>Authoritative calculations, validation and permissions</small></div><div><strong>SQLite project data</strong><small>Records, history and independently managed backups</small></div><div><strong>Read-only commercial archive</strong><small>Source documents remain under human control</small></div></div>`)}${panel('What this public edition includes','An independent, static reconstruction of the platform structure',`<div class="panel-body scope-note"><p>English interface, fictional counterparties, generated financial records, interactive local edits and synthetic document previews.</p><p>No production database, real contracts, personal account records, employer branding or source archive files are included.</p><p><strong>Demo limits:</strong> browser storage replaces the server and database. It can be cleared or lost. Role switching illustrates permissions; it is not a security boundary. There are no real uploads, authentication, payment processing or multi-user synchronization.</p><p>Hosted as a static GitHub Pages site. No automatic expiry is configured.</p></div>`)}</div>`;}
function render(){if(!visiblePage(ui.page))ui.page='overview';document.title=pages[ui.page][0]+' · Hanchen Wang';const fn={overview,entry:()=>head('New settlement','Create a fictional statement. The linked contract determines its business scope and currency.')+`<section class="panel form-panel"><div class="panel-body">${settlementForm()}</div></section>`,ledger,contracts,progress,budget,analysis:()=>budget(true),construction,cashflow,parties,areas,owner,expenses,master,users,audit,errors,about};$('#app').innerHTML=shell((fn[ui.page]||overview)());if(ui.page==='entry')updateAmountPreview($('#app form'));}
function navigate(page){if(!pages[page])return;ui.page=page;ui.query='';ui.filter='all';ui.menu=false;history.replaceState(null,'','#'+page);render();window.scrollTo(0,0);}
function field(label,name,value='',type='text',extra=''){return `<label>${E(label)}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;}
function selectField(label,name,items,value='',extra=''){return `<label>${E(label)}<select name="${name}" ${extra}>${items.map(([id,label])=>`<option value="${E(id)}"${selected(value,id)}>${E(label)}</option>`).join('')}</select></label>`;}
function amountField(label,name,value,blank=false){return field(label,name,blank||value==null?'':decimal(value),'text','inputmode="decimal" autocomplete="off" data-money="true"');}
function formFooter(text='Save demo record'){return `<p class="form-error" role="alert"></p><div class="form-actions"><span class="muted small-copy">Fictional records only · stored in this browser</span><div class="actions">${button('Cancel','close-dialog')}<button type="submit" class="btn primary">${E(text)}</button></div></div>`;}
function settlementForm(s){const cs=db().contracts.filter(c=>s?.id?c.id===s.contractId:c.scope===ui.scope&&c.status==='Active'&&party(c)?.status==='Active');const c=cs.find(c=>c.id===s?.contractId)||cs.find(c=>c.currency===ui.currency)||cs[0];if(!c)return empty('No active contract','Create an active contract before recording a settlement.');const sg=c.scope==='SG';const budgets=db().budgets.filter(b=>b.currency===c.currency);return `<form data-form="settlement" data-id="${s?.id||''}"><div class="form-grid">${selectField('Contract *','contractId',cs.map(c=>[c.id,c.code+' · '+c.name]),c.id,'required')}${field('Settlement reference *','period',s?.period||'','text','required maxlength="40" placeholder="e.g. PC-04"')}${field('Statement date *','date',s?.date||PROJECT.asOf,'date','required')}${selectField('Budget subject','budgetId',[['','Follow the contract'],...budgets.map(b=>[b.id,b.name+' · '+b.currency])],s?.budgetId||'')}<label class="check"><input name="pending" type="checkbox"${checked(s?.pending)}>Amounts awaiting confirmation</label><label class="check"><input name="final" type="checkbox"${checked(s?.final)}>Final settlement</label></div><div class="form-section"><h3>Amounts · <span id="form-currency">${c.currency}</span></h3><div class="form-grid three">${sg?amountField('Untaxed amount','certified',s?.certified, s?.pending):[amountField('Advance payment','advance',s?.advance,s?.pending),amountField('Certified amount','certified',s?.certified,s?.pending),amountField('Advance recovery','advanceRecovery',s?.advanceRecovery,s?.pending),amountField('Retention deduction / release (−)','retention',s?.retention,s?.pending),amountField('HSE deduction','hse',s?.hse,s?.pending),amountField('Other additions','additions',s?.additions,s?.pending),amountField('Other deductions','deductions',s?.deductions,s?.pending)].join('')}${amountField('Tax amount','tax',s?.tax,s?.pending)}</div><div class="live-total" id="amount-preview"></div></div><div class="form-section"><div class="form-grid"><label class="full">Remarks<textarea name="notes" maxlength="1500">${E(s?.notes||'')}</textarea></label></div></div>${formFooter(s?.id?'Save changes':'Create settlement')}</form>`;}
function formValues(form){const data=Object.fromEntries(new FormData(form));for(const k of ['pending','final','separate'])data[k]=Boolean(form.elements[k]?.checked);if(form.elements.areas)data.areas=[...form.querySelectorAll('[name="areas"]:checked')].map(i=>i.value);return data;}
function updateAmountPreview(form){if(!form||form.dataset.form!=='settlement')return;const pending=form.elements.pending.checked;form.querySelectorAll('[data-money]').forEach(i=>{i.disabled=pending;});const target=form.querySelector('#amount-preview');if(!target)return;const c=db().contracts.find(c=>c.id===form.elements.contractId.value);try{const v=formValues(form),s={pending};MONEY_FIELDS.forEach(k=>s[k]=cents(v[k]||'0'));target.innerHTML=(pending||MONEY_FIELDS.every(k=>!String(v[k]||'').trim()))?'<span>Amount is unknown. Enter an amount, including 0 for a confirmed zero. Existing Finance records are retained.</span>':`<span>Net payable <strong>${money(net(s),c.currency)}</strong></span><span>Gross payable <strong>${money(gross(s),c.currency)}</strong></span>`;}catch{target.textContent='Enter valid amounts to calculate the total.';}}
function financeForm(s){const f=db().finance.find(f=>f.settlementId===s.id),canEdit=ability('financeEdit'),paid=f?.paid||0,outstanding=s.pending?null:net(s)-paid;return `${notice(`${E(contract(s).code)} · ${E(s.period)} · ${s.currency}. Invoice and payment information is maintained separately from the commercial settlement.`)}<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Net payable',money(net(s),s.currency),s.pending?'Amount pending':'Known commercial amount')}${metric('Net paid',money(paid,s.currency),'Registered Finance amount')}${metric('Net outstanding',money(outstanding,s.currency),s.pending?'Unknown while amounts are pending':'Net payable less net paid')}</div><form data-form="finance" data-id="${s.id}"><fieldset ${canEdit?'':'disabled'} style="border:0;padding:0;margin:0"><div class="form-grid">${field('Invoice reference *','invoice',f?.invoice||'','text','required')}${field('Invoice date *','invoiceDate',f?.invoiceDate||PROJECT.asOf,'date','required')}${amountField('Invoice amount (excluding tax)','invoiceAmount',f?.invoiceAmount??net(s)??0)}${amountField('Cumulative net payment','paid',paid)}${amountField('Payment tax','tax',f?.tax||0)}${field('Payment date *','paymentDate',f?.paymentDate||PROJECT.asOf,'date','required')}${field('Payment reference','reference',f?.reference||'')}<label>Notes<textarea name="notes">${E(f?.notes||'')}</textarea></label></div></fieldset>${canEdit?formFooter('Save Finance record'):`<div class="form-actions">${tag('Finance editing not granted')}${button('Close','close-dialog')}</div>`}</form>`;}
function contractForm(c){const ps=db().parties.filter(p=>p.scope===(c?.scope||ui.scope)),scope=c?.scope||ui.scope;return `<form data-form="contract" data-id="${c?.id||''}"><div class="form-grid">${selectField('Counterparty *','partyId',ps.map(p=>[p.id,p.code+' · '+p.name]),c?.partyId||ps[0]?.id)}${field('Contract reference *','code',c?.code||'','text','required placeholder="SC01-002-WO"')}${field('Contract name *','name',c?.name||'','text','required')}${selectField('Currency','currency',[['EUR','EUR'],['USD','USD']],c?.currency||ui.currency)}${amountField('Contract value','amount',c?.amount||0)}${selectField('Lifecycle','status',[['Active','Active'],['Completed','Completed'],['Inactive','Inactive']],c?.status||'Active')}${selectField('Parent for VO / SA','parentId',[['','None — CT or WO'],...db().contracts.filter(p=>p.scope===scope&&['CT','WO','SA'].includes(p.kind)&&p.id!==c?.id).map(p=>[p.id,p.code])],c?.parentId||'')}${selectField('Construction category','category',[['','Unclassified'],...db().categories.map(c=>[c,c])],c?.category||'')}${selectField('Default budget subject','budgetId',[['','Not classified'],...db().budgets.map(b=>[b.id,b.name+' · '+b.currency])],c?.budgetId||'')}${field('Filing reference','filing',c?.filing||'')}${field('WO reference (WO only)','wo',c?.wo||'')}<label class="check"><input type="checkbox" name="separate"${checked(c?.separate)}>Calculate this SA as a standalone package</label>${scope==='SC'?`<div class="full"><span class="small-copy">Linked project areas</span><div class="form-grid three" style="margin-top:10px">${db().areas.map(a=>`<label class="check"><input type="checkbox" name="areas" value="${a.id}"${checked(c?.areas.includes(a.id))}>${a.code} · ${E(a.name)}</label>`).join('')}</div></div>`:''}</div>${formFooter(c?'Save contract changes':'Create contract')}</form>`;}
function receiptForm(){return `<form data-form="receipt"><div class="form-grid">${field('Receipt reference *','reference','','text','required placeholder="DEMO-OWNER-04"')}${field('Receipt date *','date',PROJECT.asOf,'date','required')}${selectField('Currency','currency',[['EUR','EUR'],['USD','USD']],ui.currency)}${amountField('Advance received','advance')}${amountField('Certified amount','certified')}${amountField('Advance recovery','recovery')}${amountField('Retention withheld','retained')}${amountField('Retention released','released')}${amountField('Tax received','tax')}<label class="full">Notes<textarea name="notes"></textarea></label></div>${formFooter('Create receipt')}</form>`;}
let dialogReturnFocus=null;
function modal(title,body){const dialog=$('#dialog');dialogReturnFocus=document.activeElement;dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${E(title)}</h2><button data-action="close-dialog" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();updateAmountPreview(dialog.querySelector('form'));}
function closeDialog(){const d=$('#dialog');if(d.open){d.close();dialogReturnFocus?.isConnected&&dialogReturnFocus.focus();}else navigate('ledger');}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4800);}
function files(c){if(!ability('documents')){toast('This role cannot browse sample documents.');return;}const rows=[['review','Internal review','R1','Filed'],['contract','Signed contract sample','R2','Current'],['filing','Filing receipt','R1','Filed'],['guarantee','Performance guarantee sample','R1','Restricted']];modal(c.code+' · Sample documents',notice('Fictional, read-only evidence. This public demo has no connection to a commercial archive.')+table(['Document','Revision','State','Action'],rows.map(([kind,label,rev,state])=>`<tr><td>${E(label)}</td><td>${rev}</td><td>${tag(state,state==='Current'?'green':state==='Restricted'?'amber':'')}</td><td>${kind==='guarantee'&&!ability('guarantees')?tag('Separate permission required','amber'):button('Preview','document',`data-id="${c.id}" data-kind="${kind}"`,'small')}</td></tr>`)));}
function documentPreview(title,reference,kind='contract'){return `<article class="document-preview"><div class="document-watermark">FICTIONAL DEMONSTRATION DOCUMENT</div><h3>${E(title)}</h3><p><strong>Reference</strong> ${E(reference)}<br><strong>Project</strong> ${PROJECT.name}<br><strong>Revision</strong> R2 — sample current issue</p><hr style="border:0;border-top:1px solid #ddd"><p>This sample illustrates how structured records connect to read-only supporting evidence. It is not a real ${kind==='guarantee'?'guarantee, bank instrument':'contract or commercial record'} and creates no obligation.</p><p><strong>Demonstration scope</strong><br>Review the reference, revision and related record. In the working platform, source files remain in a separately managed archive and cannot be renamed, overwritten or reorganized by the application.</p><p>All names, identifiers and values in this public edition are fictional.</p></article>`;}
function exportLedger(){const rows=visibleSettlements().filter(s=>matches(s.flow,s.period,contract(s)?.name,contract(s)?.code,party(contract(s))?.name)&&(ui.filter!=='pending'||s.pending)&&(!ui.filter.startsWith('contract:')||s.contractId===ui.filter.slice(9)));const data=[['Flow','Contract','Contract name','Counterparty','Statement','Date','Currency','Net payable','Tax','Gross payable','Net paid','Amount pending'],...rows.map(s=>[s.scope+'-'+s.flow,contract(s).code,contract(s).name,party(contract(s)).name,s.period,s.date,s.currency,s.pending?'':decimal(net(s)),s.pending?'':decimal(s.tax),s.pending?'':decimal(gross(s)),decimal(db().finance.find(f=>f.settlementId===s.id)?.paid||0),s.pending?'Yes':'No'])];const blob=new Blob([csv(data)],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`demo-${ui.scope}-settlements-${ui.currency}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo CSV exported. Pending amounts remain blank.');}
async function handleAction(el){const action=el.dataset.action,id=el.dataset.id,value=el.dataset.value;
  if(action==='navigate')return navigate(el.dataset.page);
  if(action==='menu'){ui.menu=!ui.menu;return render();}
  if(action==='scope'){ui.scope=value;ui.area='';return navigate('ledger');}
  if(action==='workspace'){ui.workspace=value;return navigate('ledger');}
  if(action==='columns'){ui.detail=!ui.detail;return render();}
  if(action==='pending'){navigate('ledger');ui.filter='pending';return render();}
  if(action==='clear-filter'){ui.filter='all';ui.query='';return render();}
  if(action==='expand'){ui.expanded.has(id)?ui.expanded.delete(id):ui.expanded.add(id);return render();}
  if(action==='expand-all'){db().contracts.forEach(c=>ui.expanded.add(c.id));return render();}
  if(action==='contract-ledger'){const c=db().contracts.find(c=>c.id===id);ui.scope=c.scope;ui.currency=c.currency;navigate('ledger');ui.filter='contract:'+id;return render();}
  if(action==='party-contracts'){const p=db().parties.find(p=>p.id===id);navigate('contracts');ui.query=p.name;return render();}
  if(action==='area'){ui.area=id;return render();}
  if(action==='owner-tab'){ui.ownerTab=value;return render();}
  if(action==='master-tab'){ui.masterTab=value;return render();}
  if(action==='close-dialog')return closeDialog();
  if(action==='edit-settlement'){if(!ability('settlementEdit'))return;const s=db().settlements.find(s=>s.id===id);return modal('Edit settlement · '+s.scope+'-'+s.flow,settlementForm(s));}
  if(action==='view-settlement'){const s=db().settlements.find(s=>s.id===id);return modal('Settlement · '+s.scope+'-'+s.flow,notice('Read-only record for the current demo role.')+`<div class="audit-diff">${E(JSON.stringify({contract:contract(s).code,reference:s.period,date:s.date,currency:s.currency,amountPending:s.pending,netPayable:money(net(s),s.currency),grossPayable:money(gross(s),s.currency),remarks:s.notes},null,2))}</div>`);}
  if(action==='finance')return modal('Finance record',financeForm(db().settlements.find(s=>s.id===id)));
  if(action==='new-contract'||action==='edit-contract'){if(!ability('contractEdit'))return;return modal(action==='new-contract'?'New contract':'Edit contract',contractForm(db().contracts.find(c=>c.id===id)));}
  if(action==='edit-budget'){if(!ability('budgetEdit'))return;const b=db().budgets.find(b=>b.id===id);return modal('Edit execution budget',`<form data-form="budget" data-id="${b.id}">${notice(E(b.name+' · '+b.currency)+'. Commitments and settlement records stay unchanged.')}<div class="form-grid">${amountField('Budget amount','amount',b.amount)}${field('Version label','version',b.version,'text','required')}</div>${formFooter('Save budget')}</form>`);}
  if(action==='new-party'){if(!ability('contractEdit'))return;return modal('New fictional counterparty',`<form data-form="party"><div class="form-grid">${field('Counterparty code *','code','','text',`required placeholder="${ui.scope}20"`)}${field('Name *','name','','text','required')}<label class="full">Notes<textarea name="notes"></textarea></label></div>${formFooter('Create counterparty')}</form>`);}
  if(action==='new-expense'){if(!ability('expenses'))return;return modal('New expense',`<form data-form="expense"><div class="form-grid">${field('Description *','description','','text','required')}${field('Date *','date',PROJECT.asOf,'date','required')}${selectField('Category','category',db().categories.map(c=>[c,c]))}${selectField('Currency','currency',[['EUR','EUR'],['USD','USD']],ui.currency)}${amountField('Net amount','net')}${amountField('Tax','tax')}</div>${formFooter('Create expense')}</form>`);}
  if(action==='new-receipt'){if(ability('ownerReceipts'))return modal('New owner receipt',receiptForm());return;}
  if(action==='files')return files(db().contracts.find(c=>c.id===id));
  if(action==='document'){if(!ability('documents')||(el.dataset.kind==='guarantee'&&!ability('guarantees')))return toast('Separate document permission required.');const c=db().contracts.find(c=>c.id===id);return modal('Sample document',documentPreview(c.name,c.code,el.dataset.kind));}
  if(action==='party-files'){if(!ability('documents'))return toast('Document permission required.');const p=db().parties.find(p=>p.id===id);return modal('Counterparty general files',documentPreview('Fictional company information sheet',p.code));}
  if(action==='owner-document'){if(!ability('ownerDocuments'))return;const d=db().ownerDocs.find(d=>d.id===id);return modal('Owner document',documentPreview(d.title,d.reference));}
  if(action==='audit-detail'){if(!ability('audit'))return;const a=db().audit.find(a=>a.id===id);return modal('Inspect change',`<p class="small-copy">${E(a.actor)} · ${E(a.action)} · ${E(a.entity)}</p><h3 class="small-copy">Before</h3><pre class="audit-diff">${E(JSON.stringify(a.before,null,2))}</pre><h3 class="small-copy">After</h3><pre class="audit-diff">${E(JSON.stringify(a.after,null,2))}</pre>`);}
  if(action==='export-ledger')return exportLedger();
  if(action==='tour-start'){ui.tour=0;ui.workspace='commercial';ui.role='admin';ui.scope='SC';ui.currency='EUR';toast('The guided tour uses the Demo Administrator role.');return navigate('overview');}
  if(action==='tour-next'){ui.tour++;if(ui.tour>=tour.length){ui.tour=-1;toast('Tour complete. Explore freely or reset the fictional dataset.');return render();}return navigate(tour[ui.tour][0]);}
  if(action==='tour-close'){ui.tour=-1;return render();}
  if(action==='reset')return modal('Reset this browser’s demo?',`<p class="scope-note">This removes your local demo edits, custom role settings and local audit history, then restores the original fictional dataset. It affects only this browser.</p><div class="form-actions">${button('Keep my changes','close-dialog')}${button('Reset fictional data','confirm-reset','','danger')}</div>`);
  if(action==='confirm-reset'){store.reset();ui.role='admin';ui.workspace='commercial';ui.scope='SC';ui.currency='EUR';ui.expanded.clear();ui.tour=-1;closeDialog();navigate('overview');toast('Original fictional data restored.');}
}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;Promise.resolve(handleAction(el)).catch(error=>{store.error(error.message);toast(error.message);});});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='role'){ui.role=el.value;ui.tour=-1;closeDialogIfOpen();navigate('overview');toast('Demo role changed to '+ROLES[ui.role]);}
  else if(el.id==='currency'){ui.currency=el.value;render();}
  else if(el.id==='month'){if(el.value){ui.month=el.value;render();}}
  else if(el.id==='status-filter'){ui.filter=el.value;render();}
  else if(el.dataset.permission){if(ui.role!=='admin')return;const key=el.dataset.permission,role=el.dataset.role,on=el.checked;store.change(ui.role,'PERMISSION',ROLES[role],next=>{const set=new Set(next.roles[role]);on?set.add(key):set.delete(key);next.roles[role]=[...set];return {id:role,capability:key,granted:on};});toast('Demo permission updated.');}
  else if(el.name==='contractId'&&el.closest('[data-form="settlement"]')){const form=el.form,id=form.dataset.id,c=db().contracts.find(c=>c.id===el.value);const data=formValues(form);ui.scope=c.scope;const temporary={...data,contractId:c.id,currency:c.currency,id,pending:data.pending,final:data.final};MONEY_FIELDS.forEach(k=>{try{temporary[k]=String(data[k]||'').trim()?cents(data[k]):undefined;}catch{temporary[k]=0;}});const container=form.parentElement;container.innerHTML=settlementForm(temporary);const newForm=container.querySelector('form');newForm.dataset.id=id;updateAmountPreview(newForm);}
  else if(el.closest('[data-form="settlement"]'))updateAmountPreview(el.form);
});
function closeDialogIfOpen(){if($('#dialog').open)$('#dialog').close();}
document.addEventListener('input',event=>{if(event.target.id==='search'){const start=event.target.selectionStart;ui.query=event.target.value;render();const input=$('#search');input.focus();if(input.type==='search')input.setSelectionRange(start,start);}else if(event.target.closest('[data-form="settlement"]'))updateAmountPreview(event.target.form);});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const input=formValues(form),kind=form.dataset.form,id=form.dataset.id;try{let result;const operations={settlement:saveSettlement,finance:saveFinance,contract:saveContract,budget:saveBudget,expense:saveExpense,receipt:saveReceipt,party:saveParty};if(!operations[kind])return;result=store.change(ui.role,id?'UPDATE':'CREATE',kind+(id?' '+id:''),next=>operations[kind](next,ui.role,input,id));closeDialogIfOpen();if(kind==='settlement'){ui.scope=result.scope;ui.currency=result.currency;ui.page='ledger';history.replaceState(null,'','#ledger');ui.filter='all';ui.query='';}render();toast(store.notice||'Saved in this browser. The demo is not a permanent database.');}catch(error){store.error(error.message);form.querySelector('.form-error').textContent=error.message;}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(pages[page])navigate(page);});
ui.page=pages[location.hash.slice(1)]?location.hash.slice(1):'overview';
render();
